-- 8. ADDITIONAL FIRST AID - 5 questions
-- ============================================================

('special', 'Jakie jest prawidłowe ułożenie osoby nieprzytomnej, ale oddychającej?', 'Đặt người bất tỉnh nhưng còn thở ở tư thế nào là đúng?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Pozycja boczna ustalona (na boku)', 'Tư thế nằm nghiêng ổn định (nằm nghiêng)', 'Na plecach z nogami ugiętymi', 'Nằm ngửa với chân gập', 'Na brzuchu', 'Nằm sấp', 'A', 'Osobę nieprzytomną, ale oddychającą należy ułożyć w pozycji bocznej ustalonej (pozycja bezpieczna), aby zapewnić drożność dróg oddechowych.', 'Người bất tỉnh nhưng còn thở phải đặt ở tư thế nằm nghiêng ổn định (tư thế an toàn) để đảm bảo đường thở thông thoáng.'),

('special', 'Co robić w przypadku krwotoku z nosa?', 'Khi bị chảy máu cam (mũi) phải làm gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Pochylić głowę do przodu i uciskać skrzydełka nosa', 'Nghiêng đầu về phía trước và bóp cánh mũi', 'Odchylić głowę do tyłu', 'Ngửa đầu ra sau', 'Przykładać lód do czoła', 'Đặt đá lên trán', 'A', 'Przy krwotoku z nosa należy pochylić głowę do przodu, uciskać skrzydełka nosa przez 10-15 minut i oddychać przez usta.', 'Khi chảy máu mũi, cần nghiêng đầu về phía trước, bóp cánh mũi trong 10-15 phút và thở bằng miệng.'),

('special', 'Jak rozpoznać wstrząs anafilaktyczny?', 'Làm sao nhận biết sốc phản vệ?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Obrzęk twarzy, trudności w oddychaniu, wysypka', 'Mặt sưng, khó thở, phát ban', 'Ból głowy i zawroty', 'Đau đầu và chóng mặt', 'Gorączka i kaszel', 'Sốt và ho', 'A', 'Wstrząs anafilaktyczny objawia się: obrzękiem twarzy i gardła, trudnościami w oddychaniu, wysypką, bladością, przyspieszonym tętnem. Wymaga natychmiastowej pomocy medycznej!', 'Sốc phản vệ biểu hiện: mặt và горло sưng, khó thở, phát ban, xanh xao, mạch nhanh. Cần cấp cứu y tế ngay lập tức!'),

('special', 'Co oznacza skrót BLS?', 'Từ viết tắt BLS có nghĩa là gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Basic Life Support (podstawowe zabiegi ratunkowe)', 'Hỗ trợ sự sống cơ bản', 'Badanie Lekarskie Specjalistyczne', 'Khám bệnh chuyên khoa', 'Bezpieczny Linia Samochodowa', 'Đường dây an toàn ô tô', 'A', 'BLS (Basic Life Support) to podstawowe zabiegi ratunkowe obejmujące: udrożnienie dróg oddechowych, sztuczne oddychanie i masaż serca.', 'BLS (Hỗ trợ sự sống cơ bản) bao gồm các biện pháp cấp cứu cơ bản: thông đường thở, thở nhân tạo và ép tim ngoài lồng ngực.'),

('special', 'Jak pomóc osobie z zadławieniem (ciało obce w drogach oddechowych)?', 'Làm thế nào giúp người bị nghẹn (dị vật trong đường thở)?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', '5 uderzeń w plecy + 5 uciśnięć brzucha (manewr Heimlicha)', '5 cái vỗ lưng + 5 lần ép bụng (nghiệm pháp Heimlich)', 'Podać dużo wody do picia', 'Cho uống nhiều nước', 'Położyć osobę na plecach', 'Đặt nằm ngửa', 'A', 'Przy zadławieniu należy wykonać 5 uderzeń w okolice międzyłopatkowe, a jeśli to nie pomoże - 5 uciśnięć nadbrzusza (manewr Heimlicha).', 'Khi bị nghẹn cần vỗ 5 lần vào vùng giữa hai xương bả vai, nếu không được thì ép 5 lần vùng thượng vị (nghiệm pháp Heimlich).'),

